/*
Approver Matrix

*/
declare @user varchar(max)='kanchana'

select * from (Select 'EBS_XL_CriticalTCodesMatrix' as TableName,'TransactionOwner' as Field, [Transaction] as 'Entitlement','NONE' as Level1Approver,'NONE' as Level2Approver,'NONE' as Level3Approver from DI_SAP_EBS_XL_CriticalTCodesMatrix WHERE (select EmployeeId from DI_M_User where Username=@user) IN(TransactionOwner) 
Union ALL select 'NOVA_ExceptionalRoleMatrix','Level1Approver,Level2Approver,Level3Approver',FLINSRoles,Level1Approver,Level2Approver,Level3Approver from DI_NOVA_ExceptionalRoleMatrix where (select EmployeeId from DI_M_User where Username=@user) in(Level1Approver,Level2Approver,Level3Approver ) 
union all select 'NOVA_ManagementRoleMatrix','Level1Approver,Level2Approver,Level3Approver',Position,Level1Approver,Level2Approver,Level3Approver from DI_NOVA_ManagementRoleMatrix where (select EmployeeId from DI_M_User where Username=@user) in(Level1Approver,Level2Approver,Level3Approver ) union all select 'NOVA_UserRoleMatrix','Level1Approver,Level2Approver,Level3Approver',Position,Level1Approver,Level2Approver,Level3Approver from DI_NOVA_ManagementRoleMatrix where (select EmployeeId from DI_M_User where Username=@user) in(Level1Approver,Level2Approver,Level3Approver ) union all 
select 'GEMS_RoleMatrix','Level1Approver,Level2Approver,Level3Approver',BusinessRoleName,Level1Approver,Level2Approver,Level3Approver from DI_GEMS_RoleMatrix where (select EmployeeId from DI_M_User where Username=@user) in(Level1Approver,Level2Approver,Level3Approver ) union all Select 'EBS_XL_PositionsMatrix','PositionText',PositionText,Level1Approver,Level1Approver,Level3Approver from DI_SAP_EBS_XL_PositionsMatrix WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver)
Union ALL Select 'EBS_XL_RolesMatrix','RoleName',RoleName, Level1Approver,Level1Approver,Level3Approver from DI_SAP_EBS_XL_RolesMatrix WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver) Union ALL 
Select 'HRFLINSRoleMatrix','BusinessRole',BusinessRole,Level1Approver,Level1Approver,Level3Approver from DI_SAP_HRFLINSRoleMatrix WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver) Union ALL Select 'GRCRoleMatrix','BusinessRoleName', BusinessRoleName,Level1Approver,Level1Approver,Level3Approver from DI_SAP_GRCRole WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver) 
Union ALL Select 'MSSL_XL_CriticalTCodeMatrix','TransactionOwner',[Transaction],'NONE','NONE','NONE' from DI_SAP_MSSL_XL_CriticalTCodeMatrix WHERE TransactionOwner IN(select EmployeeId from DI_M_User where Username=@user) 
Union ALL Select 'MSSL_XL_PositionsMatrix','PositionText',PositionText,Level1Approver,Level1Approver,Level3Approver from DI_SAP_MSSL_XL_PositionsMatrix WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver)
Union ALL Select 'MSSL_XL_RolesMatrix','RoleName',RoleName,Level1Approver,Level1Approver,Level3Approver from DI_SAP_MSSL_XL_RolesMatrix WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver) Union ALL Select 'BIRoleCategories','BusinessRole',BusinessRole,Level1Approver,Level1Approver,Level3Approver from DI_SAP_BIRoleCategories WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver)
Union ALL Select 'SRMMainRoleMatrix','BusinessRole',BusinessRole,Level1Approver,Level1Approver,Level3Approver from DI_SAP_SRMMainRoleMatrix WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver) 
Union ALL Select 'OneCard_XLRoleCatalogue','RoleName',RoleName,Level1Approver,Level1Approver,Level3Approver from DI_SMS_XLRoleCatalogue WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver)
Union ALL Select 'EndpointSystem','OWNER',E.DisplayName,'NONE','NONE','NONE' as Endpoint from DI_M_EndpointSystem E inner join DI_M_User U on E.OwnerUserId = U.Id where U.UserName=@user Union ALL Select 'IDMS Group','Group Member',G.GroupName,'','NONE','NONE' from UserGroup Ug inner join DI_M_Group G on Ug.Group_GroupId = G.Id Inner join DI_M_User U on Ug.User_UserId = u.Id where U.UserName=@user Union All Select 'VPN Matrix','Name',[Name],Level1Approver,Level1Approver,Level3Approver from DI_VPN_Matrix WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver) 
Union ALL Select 'Skype for Business ResponseGroup','NAME',[Name], Level1Approver,Level1Approver,Level3Approver from DI_SFB_ProvisioningMatrix WHERE (select EmployeeId from DI_M_User where Username=@user) IN(Level1Approver,Level1Approver,Level3Approver) 
union all select Name+ISNULL(InhouseSystemCode,''),'Inhouse System','Level1Approver,Level1Approver,Level3Approver',Level1Approver,Level1Approver,Level3Approver from DI_INH_Permission WHERE (select EmployeeId from DI_M_User where Username=@user) in(Level1Approver,Level1Approver,Level3Approver)
union all select 'SODConflicting Matrix' as TableName,'SODOwner' as Field,BusinessRole  as 'Entitlement','NONE' as Level1Approver,'NONE' as Level2Approver,'NONE' as Level3Approver from DI_SAP_SODConflictingRole WHERE (select EmployeeId from DI_M_User where Username=@user) IN(SODOwner) 
UNION ALL select W.Workf	lowName,'Approver',CAST(WD.SequenceNumber as varchar),'','','' from DI_M_WorkflowConfiguration W inner join DI_M_WorkflowConfigurationDetail WD on W.Id = WD.WorkflowConfigurationId where WD.ApprovalUserType=1 AND WD.Approver in((select Id from DI_M_User where Username=@user)) UNION ALL select 'Role' as TableName,'Role' as Field, R.RoleName as 'Entitlement','NONE' as Level1Approver,'NONE' as Level2Approver,'NONE' as Level3Approver from DI_M_Role R INNER JOIN UserRole UR on R.Id = UR.Role_RoleId WHERE UR.User_UserId in(SELECT Id from DI_M_User where username = @user ) ) as A